    const relationshipBlocks = stream.byKind.get("relationship") ?? [];
    const dashboardBlocks = stream.byKind.get("dashboard") ?? [];
    const dashboardWidgetBlocks = stream.byKind.get("dashboard-widget") ?? [];
    const widgetBlocks = stream.byKind.get("widget") ?? [];
